/_container.scss","webpack://phoenix-react/./src/assets/scss/theme/_timeline.scss","webpack://phoenix-react/./src/assets/scss/theme/_ecommerce.scss","webpack://phoenix-react/./src/assets/scss/theme/_indicator.scss","webpack://phoenix-react/./src/assets/scss/theme/_gantt-chart.scss","webpack://phoenix-react/./src/assets/scss/theme/_landing.scss","webpack://phoenix-react/./src/assets/scss/theme/_offcanvas.scss","webpack://phoenix-react/./src/assets/scss/theme/_wizard.scss","webpack://phoenix-react/./src/assets/scss/theme/_email.scss","webpack://phoenix-react/./src/assets/scss/theme/_events.scss","webpack://phoenix-react/./src/assets/scss/theme/_feed.scss","webpack://phoenix-react/./src/assets/scss/theme/root/_override.scss","webpack://phoenix-react/./src/assets/scss/theme/_setting-panel.scss","webpack://phoenix-react/./src/assets/scss/theme/_showcase.scss","webpack://phoenix-react/./src/assets/scss/theme/_calendar.scss","webpack://phoenix-react/./src/assets/scss/theme/_chat.scss","webpack://phoenix-react/./src/assets/scss/theme/_typing.scss","webpack://phoenix-react/./src/assets/scss/theme/_crm.scss","webpack://phoenix-react/./src/assets/scss/theme/_auth-card.scss","webpack://phoenix-react/./src/assets/scss/theme/_pricing.scss"],"sourcesContent":["/* -------------------------------------------------------------------------- */\n/*                                 Theme                                      */\n/* -------------------------------------------------------------------------- */\n\n@import '~bootstrap/scss/_functions';\n@import 'theme/functions';\n\n@import 'user-variables';\n@import 'theme/variables';\n\n@import 'theme/maps';\n@import '~bootstrap/scss/maps';\n\n@import '~bootstrap/scss/mixins';\n@import 'theme/mixins';\n\n@import 'theme/_utilities';\n@import '~bootstrap/scss/variables';\n// @import '~bootstrap/scss/root';\n@import 'theme/root';\n\n/*-----------------------------------------------\n|   Bootstrap Styles\n-----------------------------------------------*/\n@import 'bootstrap';\n\n/*-----------------------------------------------\n|   Theme Styles\n-----------------------------------------------*/\n@import 'theme/theme';\n","/* prettier-ignore */\n@use 'sass:math';\n@import 'colors';\n$prefix: 'phoenix-';\n// Grid containers\n//\n// Define the maximum width of `.container` for different screen sizes.\n// scss-docs-start container-max-widths\n$container-max-widths: () !default;\n$container-max-widths: map-merge(\n  (\n    sm: 540px,\n    md: 720px,\n    lg: 960px,\n    xl: 1184px,\n    xxl: 1678px\n  ),\n  $container-max-widths\n);\n\n$container-small-max-widths: (\n  sm: 540px,\n  md: 720px,\n  lg: 960px,\n  xl: 1216px\n);\n\n$grid-breakpoints: () !default;\n$grid-breakpoints: map-merge(\n  (\n    xs: 0,\n    sm: 576px,\n    md: 768px,\n    lg: 992px,\n    xl: 1200px,\n    xxl: 1540px\n  ),\n  $grid-breakpoints\n);\n\n//*-----------------------------------------------\n//|   Gutter\n//-----------------------------------------------*/\n$grid-gutter-width: 2rem !default;\n\n// Customize the light and dark text colors for use in our color contrast function.\n// $color-contrast-dark: $gray-800 !default;\n$color-contrast-dark: $black !default;\n$color-contrast-light: $white !default;\n\n// Min contrast ratio\n$min-contrast-ratio: 2 !default;\n\n//*-----------------------------------------------\n//|   Brand colors\n//-----------------------------------------------*/\n$linkedin: #0077b5 !default;\n$facebook: #3c5a99 !default;\n$twitter: #1da1f2 !default;\n$google-plus: #dd4b39 !default;\n$github: #333333 !default;\n$youtube: #ff0001 !default;\n\n$brand-colors: () !default;\n$brand-colors: map-merge(\n  (\n    'facebook': $facebook,\n    'google-plus': $google-plus,\n    'twitter': $twitter,\n    'linkedin': $linkedin,\n    'youtube': $youtube,\n    'github': $github\n  ),\n  $brand-colors\n);\n\n//*-----------------------------------------------\n//|   Border\n//-----------------------------------------------*/\n$border-width: 1px !default;\n$border-color: var(--#{$prefix}gray-200);\n\n// Options\n//\n// Quickly modify global styling by enabling or disabling optional features.\n\n$enable-shadows: true !default;\n$enable-negative-margins: true !default;\n\n// $component-active-color: var(--#{$prefix}white) !default;\n// $component-active-bg: var(--#{$prefix}primary) !default;\n\n//*-----------------------------------------------\n//|   Shadow\n//-----------------------------------------------*/\n$box-shadow: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\n// $box-shadow-sm: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\n// $box-shadow-lg: var(--#{$prefix}box-shadow-lg) !default;\n// $box-shadow-inset: 0px 0px 0px 4px rgba(56, 116, 255, 0.2) !default;\n$box-shadow-gray-400: 0px 4px 8px -6px rgba(36, 40, 46, 0.03),\n  0px 16px 8px -4px rgba(36, 40, 46, 0.03);\n\n//*-----------------------------------------------\n//|   Spacing\n//----------------------------------------------\n\n$spacer: 1rem !default;\n$spacers: () !default;\n\n$spacers: map-merge(\n  (\n    0: 0,\n    1: $spacer * 0.25,\n    2: $spacer * 0.5,\n    3: $spacer,\n    4: $spacer * 1.5,\n    5: $spacer * 2,\n    6: $spacer * 2.5,\n    7: $spacer * 3,\n    8: $spacer * 3.5,\n    9: $spacer * 4,\n    10: $spacer * 4.5,\n    11: $spacer * 5,\n    12: $spacer * 6,\n    13: $spacer * 6.5,\n    14: $spacer * 7,\n    15: $spacer * 7.5\n  ),\n  $spacers\n);\n\n//*-----------------------------------------------\n//|   Body\n//-----------------------------------------------*/\n$body-bg: $gray-soft !default;\n$body-color: $gray-900 !default;\n\n//*-----------------------------------------------\n//|   Link\n//-----------------------------------------------*/\n$link-decoration: none !default;\n$link-hover-decoration: underline !default;\n\n//*-----------------------------------------------\n//|   Components\n//-----------------------------------------------*/\n$border-radius-sm: 0.25rem !default;\n$border-radius: 0.375rem !default;\n$border-radius-lg: 0.5rem !default;\n\n//*-----------------------------------------------\n//|   Fonts Families\n//-----------------------------------------------*/\n$font-family-sans-serif: 'Nunito Sans', -apple-system, BlinkMacSystemFont,\n  'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif, 'Apple Color Emoji',\n  'Segoe UI Emoji', 'Segoe UI Symbol' !default;\n$font-family-monospace: 'SFMono-Regular', Menlo, Monaco, Consolas,\n  'Liberation Mono', 'Courier New', monospace !default;\n$font-family-base: $font-family-sans-serif;\n\n//*-----------------------------------------------\n//|   Fonts\n//-----------------------------------------------*/\n$type-scale: 1.25 !default;\n$font-size-base: 1rem !default;\n$font-sizes: (\n  '11': math.div(1, pow($type-scale, 3)) * $font-size-base,\n  // 8.19px\n  '10': math.div(1, pow($type-scale, 2)) * $font-size-base,\n  // 10.24px\n  '9': math.div(1, $type-scale) * $font-size-base,\n  // 12.80px\n  8: $font-size-base,\n  // 16px\n  7: pow($type-scale, 1) * $font-size-base,\n  //20px\n  6: pow($type-scale, 2) * $font-size-base,\n  //25px\n  5: pow($type-scale, 3) * $font-size-base,\n  // 31.25px\n  4: pow($type-scale, 4) * $font-size-base,\n  // 39.06px\n  3: pow($type-scale, 5) * $font-size-base,\n  // 48.83px\n  2: pow($type-scale, 6) * $font-size-base,\n  // 61.04px\n  1: pow($type-scale, 7) * $font-size-base // 76.29px\n) !default;\n\n$font-size-sm: $font-size-base * 0.875 !default;\n$font-size-lg: $font-size-base * 1.2 !default;\n$font-weight-thin: 100 !default;\n$font-weight-lighter: 200 !default;\n$font-weight-light: 300 !default;\n$font-weight-normal: 400 !default;\n$font-weight-medium: 500 !default;\n$font-weight-semi-bold: 600 !default;\n$font-weight-bold: 700 !default;\n$font-weight-bolder: 800 !default;\n$font-weight-black: 900 !default;\n\n$line-height-base: 1.49 !default;\n$line-height-sm: 1.2 !default;\n$line-height-lg: 1.4 !default;\n\n$h1-font-size: map_get($font-sizes, 4) !default;\n$h2-font-size: map_get($