verse($grid-breakpoints) !default;\n$navbar-vertical-width: 15.875rem !default;\n$navbar-vertical-icon-width: 1rem !default;\n\n$navbar-vertical-link-font-size: map-get($font-sizes, '9') !default;\n// $navbar-vertical-link-padding-y: 0.344rem;\n$navbar-vertical-link-padding-y: 0.35rem;\n\n$navbar-vertical-dropdown-font-size: 0.8125rem !default;\n$navbar-vertical-dropdown-link-padding-x: map-get($spacers, 2);\n$navbar-vertical-dropdown-link-padding-y: map-get($spacers, 1);\n\n$navbar-light-brand-color: var(--#{$prefix}navbar-light-brand-color) !default;\n$navbar-light-brand-hover-color: $navbar-light-brand-color !default;\n$navbar-dark-brand-color: var(--#{$prefix}navbar-dark-brand-color) !default;\n$navbar-dark-brand-hover-color: $navbar-dark-brand-color !default;\n// $navbar-vertical-label-color: $gray-700 !default;\n$navbar-vertical-footer-height: $footer-height !default;\n$navbar-footer-border-color: var(--#{$prefix}navbar-footer-border-color);\n$navbar-vertical-height: calc(100vh - $navbar-top-height);\n\n$navbar-vertical-content-height: calc(\n  100vh - var(--#{$prefix}navbar-top-height) - $navbar-vertical-footer-height\n);\n$navbar-vertical-content-padding-x: map-get($spacers, 2);\n$navbar-vertical-content-padding-y: map-get($spacers, 3);\n$navbar-vertical-label-font-size: map-get($font-sizes, '10');\n\n//*-----------------------------------------------\n//|   Utilities\n//-----------------------------------------------*/\n\n//*-----------------------------------------------\n//|   Popover\n//-----------------------------------------------*/\n$popover-bg: $white !default;\n$popover-border-color: $gray-200 !default;\n$popover-header-bg: $light !default;\n$popover-header-border-bottom-color: shade-color($white, 16%) !default;\n$popover-header-color: $headings-color !default;\n\n//*-----------------------------------------------\n//|   Toast\n//-----------------------------------------------*/\n$toast-header-color: $gray-800 !default;\n$toast-header-background-color: $white !default;\n$toast-font-size: $font-size-base !default;\n$toast-padding-x: 0;\n$toast-padding-y: map-get($spacers, 3);\n$toast-box-shadow: $box-shadow-gray-400;\n$toast-header-background-color: transparent;\n// $toast-border-color: transparent;\n$toast-header-border-color: $gray-300;\n\n//*-----------------------------------------------\n//|   Progress\n//-----------------------------------------------*/\n$progress-border-radius: $border-radius-lg !default;\n$progress-height: 0.313rem !default;\n$progress-box-shadow: 0 0 0 transparent !default;\n\n//*-----------------------------------------------\n//|   Scrollbar\n//-----------------------------------------------*/\n$scrollbar-bg: var(--#{$prefix}scrollbar-bg) !default;\n\n//*-----------------------------------------------\n//|   Alert\n//-----------------------------------------------*/\n$alert-border-radius: map-get($spacers, 2) !default;\n$alert-padding-y: map-get($spacers, 4) !default;\n$alert-padding-x: map-get($spacers, 4) !default;\n$alert-bg-scale: -80% !default;\n$alert-border-scale: -70% !default;\n$alert-color-scale: 40% !default;\n\n//*-----------------------------------------------\n//|   Link\n//-----------------------------------------------*/\n\n//*-----------------------------------------------\n//|   Navbar Default\n//-----------------------------------------------*/\n\n$navbar-vertical-collapse-width: 4rem;\n$navbar-vertical-link-collapse-padding-x: 1.5rem;\n$navbar-vertical-collapse-padding-x: 2.5rem;\n$navbar-vertical-hover-width: 12.625rem !default;\n$navbar-vertical-collapsed-hover-shadow: 0.625rem 0 0.625rem -0.5625rem var(--#{$prefix}navbar-vertical-collapsed-hover-shadow-color) !default;\n\n$navbar-vertical-border-color: var(--#{$prefix}navbar-vertical-border-color);\n$navbar-vertical-bg-color: var(--#{$prefix}navbar-vertical-bg-color);\n$navbar-vertical-label-color: var(--#{$prefix}navbar-vertical-label-color);\n$navbar-vertical-link-color: var(--#{$prefix}navbar-vertical-link-